            final IntStack invFactorial = new IntStack();

            public abstract long modulus();

            public Modulus() {
                factorial.push(1);
                invFactorial.push(1);
            }

            public long fact(int n) {
                while (factorial.size() <= n) {
                    factorial.push((int) mult(factorial.get(factorial.size() - 1), factorial.size()));
