            array[size++] = item;
        }

        public int get(int i) {
            if (i >= size) throw new AssertionError();
            return array[i];
        }

        public int size() {
            return size;
        }

        private static int[] resize(int[] array) {
            int[] newArray = new int[array.length << 1];
            System.arraycopy(array, 0, newArray, 0, array.length);
            return newArray;
        }
