#include <bits/stdc++.h>
using namespace std;

struct NumberTheory {
    struct Mod998 {
        long long modulus() { return 998244353LL; }

        long long fact(int n, vector<long long>& factorial) {
            while ((int)factorial.size() <= n) {
                factorial.push_back((factorial.back() * (long long)factorial.size()) % modulus());
            }
            return factorial[n];
        }

        long long fInv(int n, vector<long long>& invFactorial, vector<long long>& factorial) {
            int lastKnown = (int)invFactorial.size() - 1;
            if (lastKnown < n) {
                vector<long long> fInv(n - lastKnown);
                fInv[0] = mult(fact(n, factorial), modInverse(fact(n, factorial)));
                for (int i = 1; i < (int)fInv.size(); i++) {
                    fInv[i] = mult(fInv[i - 1], n - i + 1);
                }
                for (int i = (int)fInv.size() - 1; i >= 0; i--) {
                    invFactorial.push_back(fInv[i]);
                }
            }
            return invFactorial[n];
        }

        long long paritySign(long long k) {
            return (k & 1) ? modulus() - 1 : 1;
        }

        long long ncr(int n, int r, vector<long long>& factorial, vector<long long>& invFactorial) {
            if (n < 0 || r < 0 || n < r) return 0;
            return mult(fact(n, factorial), mult(fInv(r, invFactorial, factorial), fInv(n - r, invFactorial, factorial)));
        }

        long long smallInv(int n, vector<long long>& invFactorial, vector<long long>& factorial) {
            return mult(fInv(n, invFactorial, factorial), fact(n - 1, factorial));
        }

        long long add(long long a, long long b) {
            long long v = a + b;
            return v < modulus() ? v : v - modulus();
        }

        long long mult(long long a, long long b) {
            return (a * b) % modulus();
        }

        long long modInverse(long long a) {
            // Fermat's little theorem, since modulus is prime
            return powMod(a, modulus() - 2);
        }

        long long powMod(long long base, long long exp) {
            long long result = 1;
            long long cur = base % modulus();
            while (exp > 0) {
                if (exp & 1) result = (result * cur) % modulus();
                cur = (cur * cur) % modulus();
                exp >>= 1;
            }
            return result;
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    NumberTheory::Mod998 mod;
    vector<long long> factorial{1};
    vector<long long> invFactorial{1};

    // Compute inverse factorials for n + m
    mod.fInv(n + m, invFactorial, factorial);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        long long numerator = p;
        long long denominator = mod.modulus() - (n + m - i);
        long long invDenominator = mod.modInverse(denominator);
        p = mod.mult(p, n - i);
        p = mod.mult(p, invDenominator);
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long term = 0;
        term = mod.mult(term, mod.paritySign(k + 1));
        term = mod.mult(term, mod.ncr(n, k, factorial, invFactorial));
        term = mod.mult(term, m + k);
        term = mod.mult(term, mod.smallInv(k, invFactorial, factorial));
        term = mod.mult(term, phaseSize);
        answer = mod.add(answer, term);
    }

    cout << answer << "\n";

    return 0;
}

